"""Helpers for wire modules: every substitution must find its target, so a
change in the design package can never silently leave a snapshot value."""
import re

def sub(s, old, new, count=1):
    n = s.count(old)
    assert n >= count, f"wire: expected {count}x {old[:80]!r}, found {n}"
    return s.replace(old, new)

def resub(s, pattern, repl, count=1, flags=0):
    out, n = re.subn(pattern, repl, s, flags=flags)
    assert n >= count, f"wire: pattern {pattern[:80]!r} matched {n}x, expected {count}"
    return out

def const(js, name, expr):
    """Replace `const NAME = <literal>;` (array/object literal) with `const NAME = <expr>;`."""
    m = re.search(rf"const {name} = ([\[{{])", js)
    assert m, f"wire: const {name} not found"
    i = m.start(1); depth = 0; q = None
    for k in range(i, len(js)):
        c = js[k]
        if q:
            if c == "\\": continue
            if c == q: q = None
            continue
        if c in "'\"`": q = c
        elif c in "[{": depth += 1
        elif c in "]}":
            depth -= 1
            if depth == 0:
                return js[:m.start()] + f"const {name} = {expr}" + js[k + 1:]
    raise AssertionError(f"wire: unterminated const {name}")
"""/vps: plans, term discounts, disk add-on price — all from the system."""
from _w import sub, resub, const

def body(s):
    s = sub(s, "From $12.78 a month, or $10.22 a month on an annual term, with up to 40% off longer terms.",
            "From {{nxm:vps.from}} a month, or {{nxm:vps.fromAnnual}} a month on an annual term, with up to {{nxm:term.maxPct}}% off longer terms.")
    for m in (12, 24, 36):
        s = resub(s, rf'(data-c="{m}">\d yr )−\d+%', rf"\g<1>−{{{{nxm:term.{m}}}}}%")
    s = sub(s, "at $0.10 per GB per month", "at {{nxm:disk.perGb}} per GB per month")
    s = resub(s, r"yearly saves \d+%, two years saves \d+% and three years saves \d+%",
              "yearly saves {{nxm:term.12}}%, two years saves {{nxm:term.24}}% and three years saves {{nxm:term.36}}%")
    return s

def js(s):
    s = const(s, "VPS", "__NXM.vps")
    s = const(s, "TERM", "__NXM.terms")
    s = sub(s, 'href="/register">Deploy ${v.n}', 'href="${v.href}">Deploy ${v.n}')
    return s
