            '${p.i != null ? `<p class="pp"><b>${money(p.i)}</b><s>${money(p.r)}</s><span>${p.is}</span></p><p class="then">Then ${money(p.r)} a month, all-in</p>` : `<p class="pp"><b>${money(p.r)}</b><span>/month</span></p><p class="then">A month, all-in</p>`}')
    s = resub(s, r'href="/register">(<span class="nxm-bt">)?Deploy \$\{p\.n\}', lambda m: f'href="${{p.href}}">{m.group(1) or ""}Deploy ${{p.n}}')
