import "server-only";
import { introSpan, productLd, usd, vpsPlans } from "./lib";

/** The design's "Great for" line per plan — copy, keyed by the real plan slug. */
const GREAT_FOR: Record<string, string> = {
  starter: "Personal sites, dev and staging, bots, VPNs",
  standard: "WordPress, WooCommerce, small game servers, CI runners",
  pro: "Busy sites, databases, Docker stacks",
  max: "High-traffic apps, big databases, heavy workloads",
};

/** /free-vps — the plans a customer keeps after a free start, all real. */
export async function load(_p: Record<string, string>) {
  const vps = await vpsPlans();
  if (!vps.length) throw new Error("nxm free-vps: no active VPS plans");
  const cheapest = vps.reduce((a, b) => ((a.i ?? a.p) <= (b.i ?? b.p) ? a : b));
  const startSentence = cheapest.i != null
    ? `${usd(Math.round(cheapest.i * 100))} for the ${introSpan(cheapest.it)} on the ${cheapest.n} plan, then ${usd(Math.round(cheapest.p * 100))} a month`
    : `${usd(Math.round(cheapest.p * 100))} a month on the ${cheapest.n} plan`;
  return {
    data: {
      pl: vps.map((p) => ({ n: p.n, i: p.i, r: p.p, is: introSpan(p.it), cpu: p.cpu, ram: p.ram, disk: p.disk, bw: p.bw,
        g: GREAT_FOR[p.slug] ?? "", pop: p.slug === "standard" ? 1 : 0, href: p.href })),
      // the "keep a server" timeline demo, on the cheapest real plan
      keep: {
        first: cheapest.i ?? cheapest.p,
        firstLabel: cheapest.i != null ? `${usd(Math.round(cheapest.i * 100))} ${introSpan(cheapest.it)}` : `${usd(Math.round(cheapest.p * 100))} a month`,
        regularLabel: usd(Math.round(cheapest.p * 100)),
        note: `${cheapest.n}: ${startSentence}. Cancel or resize any time.`,
      },
    },
    slots: { "vps.startSentence": startSentence },
    jsonLd: [productLd("Nxeon Cloud VPS", "Start free with no card; servers you keep are NVMe cloud VPS with full root and DDoS protection.",
      "/free-vps", vps.map((p) => ({ name: `${p.n} VPS`, price: p.i ?? p.p })))],
  };
}
import "server-only";
import { gameTiers, productLd, vpsPlans } from "./lib";
import { locationCards } from "./cards";

/** /singapore-vps-hosting — real plans, deploy links pinned to sgp1. */
export async function load(_p: Record<string, string>) {
  const [vps, mc] = await Promise.all([vpsPlans("sgp1"), gameTiers("minecraft", "sgp1")]);
  if (!vps.length) throw new Error("nxm singapore: no active VPS plans");
  return {
    slots: { "plans:html": locationCards(vps, mc[0], "Singapore") },
    jsonLd: [productLd("Nxeon Singapore VPS", "NVMe cloud VPS in Singapore with full root, a dedicated IPv4 and DDoS protection.",
      "/singapore-vps-hosting", vps.map((p) => ({ name: `${p.n} VPS`, price: p.i ?? p.p })))],
  };
}
import "server-only";
import { AU_ICONS } from "../_aurora/icons";
import { esc, introSpan, usd, type GameTier, type VpsPlan } from "./lib";

/**
 * Server renderers for the design's plan cards (markup copied from the design
 * package's generated pages), filled from real plans. Intro pricing appears
 * only when a plan really has one, with its real intro term.
 */

const ROCKET = `<span class="nxm-rk"><svg class="au-ic" viewBox="0 0 24 24" aria-hidden="true">${AU_ICONS.rocket}</svg></span>`;
const ARW = `<span class="nxm-arw" aria-hidden="true">→</span>`;
export const btn = (primary: boolean, href: string, label: string) =>
  primary
    ? `<a class="nxm-btn au-hov" href="${esc(href)}">${ROCKET}<span class="nxm-bt">${esc(label)}</span>${ARW}</a>`
    : `<a class="nxm-ghost" href="${esc(href)}"><span class="nxm-bt">${esc(label)}</span></a>`;

const d = (dollars: number) => usd(Math.round(dollars * 100));

/** Location pages (Singapore / Germany VPS): the first two VPS plans + the
 *  cheapest Minecraft tier, all pinned to the region. `.lpl` grid. */
export function locationCards(vps: VpsPlan[], mc: GameTier | undefined, regionName: string) {
  const bullets = (extra: string[]) => `<ul>${extra.map((x) => `<li>${esc(x)}</li>`).join("")}</ul>`;
  const vpsCard = (p: VpsPlan, pop: boolean) => {
    const price = p.i != null
      ? `<p class="pp"><b>${d(p.i)}</b><s>${d(p.p)}</s><span>${introSpan(p.it)}</span></p><p class="then">Then ${d(p.p)} a month</p>`
      : `<p class="pp"><b>${d(p.p)}</b><span>/month</span></p><p class="then">&nbsp;</p>`;
    return `<article class="au-card lp${pop ? " pop" : ""}">${pop ? `<span class="tag">Most popular</span>` : ""}<small class="k">Cloud VPS, ${esc(p.n)}</small><h3>${p.ram} GB RAM</h3><p class="lsp">${p.cpu} vCPU, ${p.disk} GB NVMe</p>${price}${bullets(["Full root and dedicated IPv4", `${regionName} region`, "Always-on DDoS filtering", "Ready in about 47 seconds"])}${btn(pop, p.href, `Deploy in ${regionName}`)}</article>`;
  };
  const cards = vps.slice(0, 2).map((p, i) => vpsCard(p, i === 1));
  if (mc) {
    const price = mc.i != null
      ? `<p class="pp"><b>${d(mc.i)}</b><s>${d(mc.p)}</s><span>${introSpan(mc.it)}</span></p><p class="then">Then ${d(mc.p)} a month</p>`
      : `<p class="pp"><b>${d(mc.p)}</b><span>/month</span></p><p class="then">&nbsp;</p>`;
    cards.push(`<article class="au-card lp"><small class="k">Game server</small><h3>Minecraft</h3><p class="lsp">${mc.ram} GB${mc.slots ? `, ${mc.slots} player slots` : ""}</p>${price}${bullets(["One-click game installs", `${regionName} region`, "Always-on DDoS filtering", "Ready in about 47 seconds"])}${btn(false, mc.href, `Deploy in ${regionName}`)}</article>`);
  }
  return `<div class="lpl">${cards.join("")}</div>`;
}

/** Use-case pages (WordPress / Docker): every VPS plan, one recommended. `.upl` grid. */
export function useCaseCards(vps: VpsPlan[], recSlug: string, recTag: string) {
  return `<div class="upl">${vps.map((p) => {
    const rec = p.slug === recSlug;
    const price = p.i != null
      ? `<p class="pp"><b>${d(p.i)}</b><s>${d(p.p)}</s></p><p class="then">${introSpan(p.it).replace(/^f/, "F")}, then ${d(p.p)} a month</p>`
      : `<p class="pp"><b>${d(p.p)}</b></p><p class="then">a month</p>`;
    return `<article class="au-card up${rec ? " rec" : ""}">${rec ? `<span class="tag">${esc(recTag)}</span>` : ""}<h3>${esc(p.n)}</h3>${price}<ul><li>CPU<b>${p.cpu} vCPU</b></li><li>Memory<b>${p.ram} GB</b></li><li>NVMe<b>${p.disk} GB</b></li><li>Bandwidth<b>${p.bw} TB</b></li></ul>${btn(rec, p.href, `Deploy ${p.n}`)}</article>`;
  }).join("")}</div>`;
}

#!/usr/bin/env python3
"""Port the design package's homepage (source/part1-3.html) into app/nxm.

Faithful port, not a redraw: the design's own markup, CSS and script, with only
the owner's identity changes applied (IDENTITY-SPEC.md). Re-run after any change
to the design source:

    python3 tools/nxm/port_home.py

Outputs (all generated — edit this script, not them):
  app/nxm/home.css               design CSS, every selector scoped to .nxm-home
  app/nxm/_home/content.ts       header + section HTML, the home script
  public/nxm/home/*              images/logos referenced by the design
  public/nxm/three.min.js        self-hosted (the app's CSP blocks cdnjs)
"""
import json, os, re, shutil, sys

PKG = "/root/nxeon-marketing-v1/src/New Marketing Website v1/nxeon-website-handoff"
SRC, ASSETS = f"{PKG}/source", f"{PKG}/assets"
ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
PUB = f"{ROOT}/public/nxm"
os.makedirs(f"{PUB}/home", exist_ok=True)
os.makedirs(f"{ROOT}/app/nxm/_home", exist_ok=True)

p1 = open(f"{SRC}/part1.html").read()
p2 = open(f"{SRC}/part2.html").read()
p3 = open(f"{SRC}/part3.html").read()

# ── assets: same map as the package's assemble.py, copied instead of base64-inlined
A, R = ASSETS + "/", ASSETS + "/renders/"
m = {'LOGO_SAMSUNG':A+'logos/samsung.svg','LOGO_AWS':A+'logos/aws.svg','LOGO_AZURE':A+'logos/azure.svg','LOGO_OVH':A+'logos/ovh.svg','TOUR1':A+'tour/t1.webp','TOUR2':A+'tour/t2.webp','TOUR3':A+'tour/t3.webp','TOUR4':A+'tour/t4.webp','LOGO_CLAUDE':A+'logos/claude.svg','LOGO_OPENAI':A+'logos/openai.svg','LOGO_DISCORD':A+'logos/discord.svg','LOGO_STEAM':A+'logos/steam.svg','LOGO_WORDPRESS':A+'logos/wordpress.svg','LOGO_SHOPIFY':A+'logos/shopify.svg','LOGO_CLOUDFLARE':A+'logos/cloudflare.svg','LOGO_LETSENCRYPT':A+'logos/letsencrypt.svg','LOGO_DOCKER':A+'logos/docker.svg','LOGO_GITHUB':A+'logos/github.svg','LOGO_UBUNTU':A+'logos/ubuntu.svg','LOGO_AMD':A+'logos/amd.svg','LOGO_INTEL':A+'logos/intel.svg','LOGO_NVIDIA':A+'logos/nvidia.svg','GRAIN':A+'grain.png','HERO2AURORA':A+'hero2_aurora.webp','HERO2AUR':A+'hero2_aur.png','HERO2':A+'hero2.webp','HERO2MASK':A+'hero2_mask.png','VPSUI':A+'vps_ui.webp','SITEHERO':A+'site_hero.webp','HEROMASK':A+'hero_mask.png','LOGO':A+'logo.png','NAV_MINECRAFT':A+'nav/minecraft.webp','NAV_RUST':A+'nav/rust.webp','NAV_PALWORLD':A+'nav/palworld.webp','NAV_VALHEIM':A+'nav/valheim.webp','NAV_ARK':A+'nav/ark.webp','NAV_CS2':A+'nav/cs2.webp','NXLABS':A+'nxlabs.png','HERO':A+'hero.webp','CLOUD':A+'cloud.webp','DASH':A+'dash.webp','SERVER':A+'server.webp','FILES':A+'files.webp','UPGRADE':A+'upgrade.webp','GAMES':A+'games.webp','RACK':R+'rack.webp','FIBER':R+'fiber.webp'}
for g in ['minecraft','valheim','cs2','zomboid','rust','palworld','ark','terraria','7dtd']:
    m['G_'+g.upper()] = A+f'g/{g}.webp'; m['GT_'+g.upper()] = A+f'g/{g}_t.webp'
url = {}
for k, p in m.items():
    name = os.path.relpath(p, ASSETS).replace('/', '-')
    shutil.copyfile(p, f"{PUB}/home/{name}")
    url[k] = f"/nxm/home/{name}"
shutil.copyfile(f"{SRC}/three.min.js", f"{PUB}/three.min.js")

def fill(s):
    for k in sorted(url, key=len, reverse=True):
        s = s.replace(f'__IMG_{k}__', url[k])
    left = re.findall(r'__IMG_[A-Z0-9_]+__', s)
    assert not left, left
    return s

# ── links: temporary claude.ai preview URLs → real routes (docs/url-map.json);
#    absolute nxeon.cloud links → relative, so staging stays on staging
# links: shared with every other page (tools/nxm/nxmlib.py) — preview URLs to
