def blocks(s):
    i, out = 0, []
    while True:
        j = s.find('{', i)
        if j < 0: break
        depth, k = 0, j
        while True:
            if s[k] == '{': depth += 1
            elif s[k] == '}':
                depth -= 1
                if depth == 0: break
            k += 1
        out.append((s[i:j].strip(), s[j+1:k])); i = k + 1
    return out

def split_sel(sel):
    parts, depth, cur = [], 0, ''
    for ch in sel:
        if ch in '([': depth += 1
        elif ch in ')]': depth -= 1
        if ch == ',' and depth == 0: parts.append(cur); cur = ''
        else: cur += ch
    parts.append(cur)
    return [p.strip() for p in parts if p.strip()]

