ROOTCLS = ':root.nxm-home-root'
def scope(sel):
    s = sel
    if s.startswith(':root'): return '.nxm-home' + s[5:]
    if s == 'html': return ROOTCLS
    if s == 'body': return '.nxm-home'
    if re.match(r'^html\b', s): return ROOTCLS + s[4:]
    if re.match(r'^body\b', s): return ROOTCLS + ' ' + s
    return '.nxm-home ' + s

hoisted, scoped = [], []
def walk(bl, out):
    for pre, body in bl:
        if pre.startswith(('@keyframes', '@font-face', '@property', '@-webkit-keyframes')):
            hoisted.append(f"{pre}{{{body}}}")
        elif pre.startswith(('@media', '@supports', '@container', '@layer')):
            inner = []; walk(blocks(body), inner)
            out.append(f"{pre}{{{''.join(inner)}}}")
        else:
            out.append(','.join(scope(x) for x in split_sel(pre)) + '{' + body + '}')
