} from "@/components/marketing/PricingExplorer";

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Pricing",
  description:
    "One place to compare every Nxeon product — Cloud VPS, game servers, shared web hosting, business email and domains. Live catalogue prices, monthly billing, no lock-in.",
  alternates: { canonical: "/pricing" },
};

/* Deploy CTA target — the same href the previous pricing page's plan CTAs used. */
const DEPLOY_HREF = "/register";
const DOMAINS_HREF = "/domains";

function gb(mb: number): string {
  return `${(mb / 1024).toFixed(mb % 1024 ? 1 : 0)} GB`;
}
/** Base MONTHLY price for a plan. VPS/Hosting store a monthly `priceCents`; Email &
 *  Game store it per `termMonths`, so normalise to a per-month figure. All display
 *  math downstream runs THIS through termPriceCents — the formula checkout charges. */
function monthlyOf(p: { priceCents: number; termMonths?: number }): number {
  const t = p.termMonths ?? 1;
  return t > 1 ? Math.round(p.priceCents / t) : p.priceCents;
}

const INCLUDED: Record<ProductId, string[]> = {
  vps: ["Full root access", "Dedicated IPv4", "NVMe SSD", "DDoS protection", "Auto backups", "1-click reinstall"],
  game: ["DDoS protection", "Full control panel", "Instant deploy", "Game file manager", "Custom jar support"],
  hosting: ["Free SSL", "1-click WordPress", "Free migration", "cPanel included", "DDoS protection"],
  email: ["Webmail + IMAP/SMTP", "Spam & virus filtering", "Shared calendars & contacts", "Automatic MX/SPF setup"],
  domains: ["Free WhoisGuard privacy", "Full DNS management", "One-click VPS pointing", "Auto-renew"],
};

const FAQ = [
  { q: "How does billing work across products?", a: "Every Nxeon product — VPS, game servers, shared hosting, business email and domains — is prepaid from your wallet balance, monthly by default. VPS also offers optional annual and multi-year terms at a discount. Whatever term you choose, services auto-renew at exactly that same price — the price you sign up at is the price you renew at — and nothing locks you in: cancel anytime and billing stops at the end of the current period." },
  { q: "Is the first month really free?", a: "On shared web hosting, yes — your first month is on us, then the plan renews at exactly the regular monthly price you see. The free-month offer applies to shared hosting only; VPS, game servers, business email and domains bill their regular price from month one." },
  { q: "Are the prices shown what I actually pay?", a: "Yes. Every price on this page is read live from the same catalogue the checkout charges from, so the number you see is the number you pay. Domain extensions show an indicative starting price — search a name for the exact live figure." },
];

export default async function PricingPage() {
  // Every product line's prices, read LIVE from the catalogue. Nothing below is
  // hard-coded; a catalogue edit or deactivation propagates here automatically.
  const [vpsPlans, hostingPlans, emailPlans, gamePlans] = await Promise.all([
    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
    db.hostingPlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }),
    db.emailPlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }),
    db.gamePlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }),
  ]);

  // The REAL, live annual discount + add-on prices (admin settings) — never
  // marketing constants. These are the SAME figures lib/order.ts bills, so the
  // add-on builder's "your build" total is displayed === charged.
  const [annualPct, backupPlusCents, extraDiskGbCents] = await Promise.all([
    annualDiscountPct(),
    backupPlusMonthlyCents(),
    extraDiskPerGbCents(),
  ]);

  // Promo copy from the single source of truth — surfaced ONLY where the owner
  // scoped it (shared web hosting) via firstMonthFreeAppliesTo("HOSTING"). It is
  // passed as a nullable label so the badge cannot render on any other product.
  const hostingPromoLabel = firstMonthFreeAppliesTo("HOSTING") ? currentPromo(new Date()).label : null;

  // CREATOR PARTNER PROGRAM: this must be visible BEFORE the customer's first
  // purchase (the owner's own requirement), including on this public pricing
  // page, before they've even registered. Two cases:
  //  - Signed in and already attached: read the REAL attachment (permanent,
  //    survives the cookie expiring) and show their actual tier (50%/10%).
  //  - Anonymous but carrying a valid `nxeon_ref` cookie for an ACTIVE partner
  //    code: they have no attachment yet (that's created at registration), so
  //    this is always framed as the 50% first-purchase preview.
  // Neither path touches per-order pricing (VPS/game quotes resolve their own,
  // real tier server-side) — this is messaging only, ahead of checkout.
  const jar = await cookies();
  const signedInUser = await currentUser();
  let partnerBanner: string | null = null;
  if (signedInUser) {
    const preview = await partnerPreviewForUser(signedInUser.id);
    if (preview.active) {
      partnerBanner =
        preview.tier === "FIRST"
          ? `You'll get 50% off your first order with ${preview.partnerName} — any service except domains.`
          : `You get 10% off every order, forever, with ${preview.partnerName} — any service except domains.`;
    }
  } else {
    const refCode = jar.get("nxeon_ref")?.value;
    const preview = refCode ? await partnerPreviewForCode(refCode) : { active: false, partnerName: null };
    if (preview.active) {
      partnerBanner = `You'll get 50% off your first order with ${preview.partnerName} — any service except domains. Sign up to claim it.`;
    }
  }

  // ── VPS: 4 tiers. Middle = "Most popular" (violet), last = "Best value" (cyan). ──
  const vps: ExplorerPlan[] = vpsPlans.map((p, i) => ({
    id: p.id,
    name: p.name,
    monthlyCents: monthlyOf(p),
    // Optional LOW intro price → the card shows "$intro first term, then $regular/mo".
    // Null (no intro set) leaves the card at the plain regular price, unchanged.
    introMonthlyCents: planIntroMonthlyCents(p),
    badge:
      vpsPlans.length >= 3 && i === Math.floor((vpsPlans.length - 1) / 2)
        ? "popular"
        : vpsPlans.length >= 3 && i === vpsPlans.length - 1
          ? "best"
          : undefined,
    specs: [
      { label: "CPU", value: `${p.cpuCores} vCPU` },
      { label: "RAM", value: gb(p.ramMB) },
      { label: "Storage", value: `${p.diskGB} GB NVMe` },
      { label: "Bandwidth", value: `${p.bandwidthTB} TB` },
    ],
    href: DEPLOY_HREF,
  }));

  // ── Hosting: featured tier gets the violet "Most popular" badge. ──
  const hosting: ExplorerPlan[] = hostingPlans.map((p, i) => ({
    id: p.id,
    name: p.name,
    monthlyCents: monthlyOf(p),
    badge: p.featured || (hostingPlans.length >= 3 && i === Math.floor((hostingPlans.length - 1) / 2)) ? "popular" : undefined,
    specs: [
      { label: "Disk", value: `${p.diskGB} GB` },
      { label: "Websites", value: String(p.maxSites) },
      { label: "Databases", value: String(p.maxDatabases) },
      { label: "Bandwidth", value: `${p.bandwidthTB} TB` },
      { label: "Mailboxes", value: p.mailboxes < 0 ? "Unlimited" : String(p.mailboxes) },
    ],
    href: DEPLOY_HREF,
  }));

  // ── Business Email: mailbox plans. ──
  const email: ExplorerPlan[] = emailPlans.map((p, i) => ({
    id: p.id,
    name: p.name,
    monthlyCents: monthlyOf(p),
    badge: emailPlans.length >= 3 && i === Math.floor((emailPlans.length - 1) / 2) ? "popular" : undefined,
    specs: [
      { label: "Mailboxes", value: `${p.mailboxes} mailbox${p.mailboxes === 1 ? "" : "es"}` },
      { label: "Storage", value: `${p.storageGB} GB / mailbox` },
      { label: "Filtering", value: "Spam & virus" },
      { label: "Sync", value: "Calendars & contacts" },
    ],
    href: DEPLOY_HREF,
  }));

  // ── Game servers: grouped by family, canonical order, families with real plans only. ──
  const byGame = new Map<string, typeof gamePlans>();
  for (const g of gamePlans) {
    if (!byGame.has(g.gameFamily)) byGame.set(g.gameFamily, []);
    byGame.get(g.gameFamily)!.push(g);
  }
  const games: ExplorerGameFamily[] = GAME_FAMILIES.filter((f) => (byGame.get(f)?.length ?? 0) > 0).map((fam) => {
    const tiers = (byGame.get(fam) ?? []).slice().sort((a, b) => a.priceCents - b.priceCents);
    return {
      id: fam,
      name: GAME_DISPLAY[fam].name,
      plans: tiers.map((t) => ({
        id: t.id,
        name: t.name,
        monthlyCents: monthlyOf(t),
        // Same optional LOW intro price as VPS above — GamePlan carries the same
        // introPriceCents/introTermMonths columns (2026-09-17 grandfather program).
        introMonthlyCents: planIntroMonthlyCents(t),
        badge: t.featured ? ("popular" as const) : undefined,
        specs: [
          { label: "RAM", value: gb(t.ramMB) },
          { label: "CPU", value: `${t.cpuCores} vCPU` },
          { label: "Storage", value: `${t.diskGB} GB` },
          ...(t.slots != null ? [{ label: "Slots", value: `${t.slots} slots` }] : []),
        ],
        href: DEPLOY_HREF,
      })),
    };
  });

  const tlds = POPULAR_TLDS.map((t) => ({ tld: t.tld, fromCents: t.fromCents }));

  return (
    <>
      {vpsPlans.length > 0 && <ProductJsonLd plans={vpsPlans} />}
      <FaqJsonLd items={FAQ} />

      {/* No `overflow-hidden` here: it was slicing the plan-card glows and the
          per-panel/hero auras with a hard rectangular edge at the layout sides.
          Box-shadow glows never create a scrollbar, and the ambient layer is
          `absolute inset-0` (self-contained), so nothing here needs clipping —
          the one element that could bleed horizontally (the panel aura) is
          contained to `inset-x-0` in PricingExplorer instead. */}
      <div className="relative min-h-screen">
        {/* Ambient dot-field + violet/blue aura for depth (the v5 signature). */}
        <div aria-hidden className="pointer-events-none absolute inset-0 z-0">
          <AmbientField />
          <div className="absolute inset-0 hero-aura opacity-80" />
        </div>

        <div className="relative z-10">
          {partnerBanner && (
            <div className="mx-auto mb-6 flex max-w-[1100px] items-center justify-center gap-2 rounded-xl border border-emerald-500/30 bg-emerald-500/10 px-4 py-3 text-center text-sm font-semibold text-emerald-300">
              {partnerBanner}
            </div>
          )}
          <PricingExplorer
            annualPct={annualPct}
            vps={vps}
            hosting={hosting}
            email={email}
            games={games}
            tlds={tlds}
            hostingPromoLabel={hostingPromoLabel}
            included={INCLUDED}
            domainsHref={DOMAINS_HREF}
            backupPlusCents={backupPlusCents}
            extraDiskPerGbCents={extraDiskGbCents}
            reviewBadges={<ReviewBadges />}
          />
        </div>
      </div>
    </>
  );
}
/**
 * VPS INTRO PRICING — a LOW first-term price that RENEWS at the regular price
 * (classic hosting promo: "$3.99/mo first term, renews at $6.49/mo").
 *
 * This is deliberately modelled as a FIRST-TERM-ONLY discount so it rides the
 * plumbing the platform already has, rather than adding a second renewal price:
 *
 *   - The ORDER (lib/order.ts) charges the intro-reduced first term and stamps the
 *     implied first-term rate on `Server.termPromoPercent` (the very column every
 *     later proration/refund already prices against — see lib/proration.ts).
 *   - RENEWAL (lib/renewal-charge.ts — the SINGLE renewal formula) reads
 *     `plan.priceCents` and knows NOTHING about `introPriceCents`, so a renewal is
 *     billed at the regular price by construction. No renewal code changes.
 *
 * Pure & deterministic (no `db`, no I/O), so it can be imported by the order core,
 * the marketing pricing cards and unit tests alike. The two READERS below cast to
 * reach `introPriceCents` / `introTermMonths` because the symlinked prod Prisma
 * client's types predate these columns until it is regenerated at deploy — the
 * same stale-client gap `frozenProductAnnualPct` (lib/product-billing.ts) and the
 * `Server` writes in lib/order.ts already work around. Identical at runtime once
 * the client is regenerated.
 */
import { termDiscountPct } from "./billing-terms";

/** A row that MAY carry the intro columns (present at runtime, absent from stale types). */
type PlanIntroFields = { introPriceCents?: number | null; introTermMonths?: number | null };

/**
 * The plan's intro MONTHLY price in cents, or null when it is unset, malformed, or
 * NOT genuinely below the regular price. Requiring `intro < regular` means a bad /
 * equal / higher value can never quietly RAISE the first-term charge — it just
 * disables the intro and the plan bills its regular price.
 *
 * `plan` is typed loose on the intro column because the symlinked prod Prisma client's
 * types predate it (regenerated at deploy); the value is present at runtime.
 */
export function planIntroMonthlyCents(plan: { priceCents: number }): number | null {
  const v = (plan as PlanIntroFields).introPriceCents;
  if (typeof v !== "number" || !Number.isFinite(v) || v < 0) return null;
  const cents = Math.round(v);
  if (cents >= plan.priceCents) return null;
  return cents;
}

/**
 * How many of the first term's months are billed at the intro rate. NULL / invalid
 * => the WHOLE first term (returned as null so callers apply it across every month).
 * Clamped to >= 1 so a stray 0 can never zero the intro window. `plan` is `unknown`
 * for the same stale-client reason as above.
 */
export function planIntroTermMonths(plan: unknown): number | null {
  const v = (plan as PlanIntroFields | null | undefined)?.introTermMonths;
  if (typeof v !== "number" || !Number.isFinite(v) || v < 1) return null;
  return Math.round(v);
}

/**
 * Cents knocked off the FIRST term because of the intro rate — 0 when there is no
 * intro. Expressed as a REDUCTION of the regular term total (not a second price)
 * so the regular term price stays the single source of truth and the renewal math
 * is untouched:
 *
 *   discount = (regularMonthly − introMonthly) × introMonths × (1 − termDiscount)
 *
 * `introMonths` is `min(introTermMonths ?? months, months)`, so a 1-month term is
 * fully intro-priced, and a "$3.99 first month" intro on a 12-month first order
 * discounts exactly one month and bills the other eleven at the regular rate.
 * The term discount is applied so the intro months are discounted consistently
 * with the rest of the term the customer chose.
 */
export function introFirstTermDiscountCents(
  regularMonthlyCents: number,
  introMonthlyCents: number | null,
  termMonths: number,
  introTermMonths: number | null,
  annualDiscountPct?: number,
): number {
  if (introMonthlyCents == null || introMonthlyCents >= regularMonthlyCents) return 0;
  const months = Math.max(1, Math.round(termMonths));
  const introMonths = introTermMonths != null ? Math.min(introTermMonths, months) : months;
  if (introMonths <= 0) return 0;
  const pct = termDiscountPct(months, annualDiscountPct);
  return Math.max(0, Math.round((regularMonthlyCents - introMonthlyCents) * introMonths * (1 - pct / 100)));
}

/**
 * The percent OFF the regular term total that the intro first term represents,
 * as a whole number 0..100 — the value stamped on `Server.termPromoPercent` so
 * proration and refunds price against the rate the term was actually sold at.
 * Integer because it round-trips through Stripe metadata as an integer promo
 * percent (lib/order.ts parseOrderPrice), exactly like the seasonal promos.
 */
export function introSoldPercent(regularTermCents: number, introDiscountCents: number): number {
  if (regularTermCents <= 0 || introDiscountCents <= 0) return 0;
  return Math.min(100, Math.max(0, Math.round((introDiscountCents / regularTermCents) * 100)));
}
/**
 * Billing term definitions + discount math, shared by ordering, renewal,
 * the deploy wizard, invoices and the domain flow. Discounts are the platform's
 * promo (longer commitment = cheaper); tune here (or later via admin Settings).
 */

export type VpsTerm = { months: number; label: string; short: string; discountPct: number };

/** The ANNUAL term is 12 months — the one term whose discount is admin-configurable. */
export const ANNUAL_TERM_MONTHS = 12;

/**
 * The annual (12-month) commitment discount SHIPPED as the default, and the fallback
 * for the `annual_discount_percent` admin setting (lib/annual-discount.ts).
 *
 * It MUST equal the 12-month `VPS_TERMS` discountPct below: a platform whose
 * `Setting` table has no `annual_discount_percent` row must price the annual term
 * EXACTLY as it did before the setting existed, so no existing annual server's
 * renewal price moves the moment this wiring lands. The setting only ever raises or
 * lowers it deliberately, from the admin Billing panel.
 */
export const DEFAULT_ANNUAL_DISCOUNT_PCT = 20;

export const VPS_TERMS: VpsTerm[] = [
  { months: 1, label: "Monthly", short: "1 mo", discountPct: 0 },
  // Annual is admin-configurable — this is only the SHIPPED default. Every charge
  // path resolves the live rate via `annualDiscountPct()` and passes it through
  // `vpsTermPriceCents`; this constant is what an un-wired caller (and a 2-arg call)
  // falls back to. Keep it === DEFAULT_ANNUAL_DISCOUNT_PCT.
  { months: 12, label: "Annual", short: "1 yr", discountPct: DEFAULT_ANNUAL_DISCOUNT_PCT },
  // Biennial/Triennial are FIXED platform rates (NOT admin-configurable), so for these
  // terms the order and every renewal read the SAME constant here → displayed ===
  // charged === renewed by construction, with no per-account freezing needed. Editing a
  // rate here only reprices NEW orders; any existing longer-term account simply renews
  // at the new (always-cheaper) rate — never an overcharge.
  { months: 24, label: "Biennial", short: "2 yr", discountPct: 30 },
  { months: 36, label: "Triennial", short: "3 yr", discountPct: 40 },
];

export function vpsTerm(months: number): VpsTerm {
  return VPS_TERMS.find((t) => t.months === months) ?? VPS_TERMS[0];
}

/**
 * The discount percent to apply to a term.
 *
 * For the ANNUAL (12-month) term this is admin-configurable: pass the
 * `annualDiscountPct` resolved from the `annual_discount_percent` setting
 * (lib/annual-discount.ts) and it WINS over the shipped default. Every other term
 * keeps its fixed `VPS_TERMS` rate. Omitting the override — or passing a
 * non-finite value — falls back to the shipped default, so a 2-arg
 * `vpsTermPriceCents` call and any caller that has not been wired up price annual at
 * `DEFAULT_ANNUAL_DISCOUNT_PCT`, i.e. exactly what the platform shipped before.
 * Clamped to 0..90 here as a second line of defence behind the setting reader.

