/**
 * Genre tags, used by the deploy wizard's game picker to offer filter chips.
 *
 * These are FACTS ABOUT THE GAMES, not claims about Nxeon — Rust is a survival
 * game whoever is hosting it — which is why they can live in a static catalog
 * here rather than needing a column. They sit next to GAME_DISPLAY for the same
 * reason that map exists: the picker, the marketing pages and anything else that
 * wants to group games all read ONE list, instead of each growing its own copy
 * that drifts (the exact bug the GAME_DISPLAY comment above records).
 *
 * The vocabulary is deliberately CLOSED (the `Genre` union). An open-ended tag
 * string would let a typo — "Suvival" — silently become a seventh filter chip
 * showing one game, because the chip row is built from the genres actually
 * present rather than from a second hardcoded list.
 *
 * A family may be absent: it then answers only to "All games". Nothing here is
 * a popularity or sales signal — there is no honest one in the schema (every
 * active family carries a `featured` PLAN, which marks a tier inside a family,
 * not a favoured game), so the picker has no "Popular" chip.
 */
export type Genre = "Survival" | "Action" | "RPG" | "FPS" | "Strategy" | "Sandbox";

/** Chip order in the picker. Only genres with at least one game are shown. */
export const GENRE_ORDER: Genre[] = ["Survival", "Action", "RPG", "FPS", "Strategy", "Sandbox"];

