import "server-only";
import { existsSync } from "node:fs";
import { join } from "node:path";
import { db } from "@/lib/db";
import { deployHref, DEPLOY_PARAM } from "@/lib/deploy-intent";
import { backupPlusMonthlyCents } from "@/lib/backup-upgrade";
import { BACKUP_PLUS_KEEP } from "@/lib/backup-tiers";
import { dedicatedIpMonthlyCents } from "@/lib/dedicated-ip";
import { EXTRA_DISK_MAX_ADD_GB, EXTRA_DISK_STEP_GB, maxAddableExtraDiskGB } from "@/lib/extra-disk";
import { firstMonthFreeAppliesTo, firstMonthFreeEnabled } from "@/lib/promo-redemption";
import { currentPromo } from "@/lib/promotions";
import { planIntroMonthlyCents } from "@/lib/intro-pricing";
import { hostingAppMenu } from "@/lib/hosting-app-menu";
import { regionsFrom } from "@/lib/nx/catalog";
import { GAME_ART_SLUG, GAME_DISPLAY, GAME_FAMILIES, GAME_GENRES, GENRE_ORDER, type GameFamily } from "@/lib/games";
import { POPULAR_TLDS } from "@/components/marketing/tlds";
import { esc, gameTiers, introSpan, usd, vpsPlans, vpsTermMap, diskPerGb, type GameTier, type VpsPlan } from "./lib";

/**
 * The whole live catalogue for the pricing panel (/pricing) and the homepage's
 * prices, read at request time from the same tables and helpers the deploy
 * wizard and checkout use (Plan, GamePlan, HostingPlan, EmailPlan, OsTemplate,
 * enabled Node regions, the admin add-on prices, the term ladder, the promo
 * gate). Nothing is a snapshot; a missing product line throws.
 */

const cents = (dollars: number) => Math.round(dollars * 100);
const d = (dollars: number) => usd(cents(dollars));

export type GameFam = {
  k: string; name: string; genres: string[]; art: string | null;
  /** most players any tier holds (real slot count) */ pl: number;
  /** cheapest monthly price, intro-first (same rule as the deploy wizard's "from") */ from: number;
  tiers: { id: string; g: number; s: number | null; p: number; i: number | null; is: string; cpu: number; disk: number; href: string }[];
};

/** Real key art for a family (public/games/art via GAME_ART_SLUG), resized by
 *  the app's own image optimizer so a grid of 40+ tiles stays light. */
function artFor(family: string): string | null {
  const slug = GAME_ART_SLUG[family as GameFamily];
  if (!slug) return null;
  for (const f of [`${slug.hero}_hero.jpg`, slug.poster ? `${slug.poster}_poster.jpg` : ""]) {
    if (f && existsSync(join(process.cwd(), "public/games/art", f))) {
      return `/_next/image?url=${encodeURIComponent(`/games/art/${f}`)}&w=640&q=75`;
    }
  }
  return null;
}

export async function gameFamilies(): Promise<GameFam[]> {
  const tiers = await gameTiers();
  const by = new Map<string, GameTier[]>();
  for (const t of tiers) by.set(t.family, [...(by.get(t.family) ?? []), t]);
  // canonical family order (lib/games.ts), families with a live plan only; any
  // family with plans but missing from the registry still shows, after them
  const order = [...GAME_FAMILIES.filter((f) => by.has(f)), ...[...by.keys()].filter((f) => !(GAME_FAMILIES as readonly string[]).includes(f))];
  return order.map((k) => {
    const ts = by.get(k)!;
    return {
      k, name: GAME_DISPLAY[k as GameFamily]?.name ?? k,
      genres: (GAME_GENRES[k as GameFamily] ?? []).slice(),
      art: artFor(k),
      pl: Math.max(0, ...ts.map((t) => t.slots ?? 0)),
      from: Math.min(...ts.map((t) => t.i ?? t.p)),
      tiers: ts.map((t) => ({ id: t.id, g: t.ram, s: t.slots, p: t.p, i: t.i, is: introSpan(t.it), cpu: t.cpu, disk: t.disk, href: t.href })),
    };
  });
}

export type Catalog = Awaited<ReturnType<typeof pricingCatalog>>;

export async function pricingCatalog() {
  const [vps, terms, perGb, perGbCents, games, hostingRows, emailRows, nodes, oses, backupCents, ipCents, promoOn] = await Promise.all([
    vpsPlans(), vpsTermMap(), diskPerGb(), import("@/lib/disk-expand").then((m) => m.extraDiskPerGbCents()),
    gameFamilies(),
    db.hostingPlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }),
    db.emailPlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }),
    db.node.findMany({ where: { enabled: true }, select: { id: true, region: true }, orderBy: { id: "asc" } }),
    db.osTemplate.findMany({ where: { active: true, category: "PLAIN_OS" }, orderBy: [{ sortOrder: "asc" }, { name: "asc" }] }),
    backupPlusMonthlyCents(), dedicatedIpMonthlyCents(),
    firstMonthFreeEnabled(),
  ]);
  if (!vps.length) throw new Error("nxm pricing: no active VPS plans");
  if (!games.length) throw new Error("nxm pricing: no active game plans");
  if (!hostingRows.length) throw new Error("nxm pricing: no active hosting plans");
  if (!emailRows.length) throw new Error("nxm pricing: no active email plans");
  const regions = regionsFrom(nodes);
  if (!regions.length) throw new Error("nxm pricing: no enabled regions");

  const hosting = hostingRows.map((h) => ({
    id: h.id, n: h.name, p: h.priceCents / 100, st: h.diskGB, sites: h.maxSites, db: h.maxDatabases, bw: h.bandwidthTB,
    mailboxes: h.mailboxes, featured: h.featured,
    href: deployHref({ service: "hosting", hostingPlanId: h.id }),
  }));
  const email = emailRows.map((e) => {
    const per = (c: number) => (e.termMonths > 1 ? c / e.termMonths : c) / 100;
    return { id: e.id, n: e.name, p: per(e.priceCents), box: e.mailboxes, gb: e.storageGB, href: deployHref({ service: "email", emailPlanId: e.id }) };
  });
  const hostingPromo = firstMonthFreeAppliesTo("HOSTING") && promoOn ? currentPromo(new Date()).label : null;

  const os = oses.map((o) => {
    const at = o.version ? o.name.indexOf(o.version) : -1;
    return { v: o.name, t: at > 0 ? o.name.slice(0, at).trim() : o.name, sub: at > 0 ? o.name.slice(at).trim() : "", fam: o.family };
  });
  if (!os.length) throw new Error("nxm pricing: no active operating systems");
  // default: the newest Ubuntu when offered (the design's default), else the first
  const ub = os.filter((o) => o.fam === "ubuntu").sort((a, b) => b.v.localeCompare(a.v, undefined, { numeric: true }))[0];
  const os0 = (ub ?? os[0]).v;

  const regionList = regions.map((r) => ({ code: r.key, city: r.name.split(",")[0].trim(), flag: r.flag, area: r.area, lat: r.lat, lon: r.lon, label: r.name }));
  const minVps = vps.reduce((a, b) => ((a.i ?? a.p) <= (b.i ?? b.p) ? a : b));

  return {
    vps, terms, perGb, perGbCents, games, hosting, email, hostingPromo, os, os0, regions: regionList,
    backup: backupCents / 100, backupKeep: BACKUP_PLUS_KEEP, ip: ipCents / 100,
    diskStep: EXTRA_DISK_STEP_GB, diskMaxAdd: EXTRA_DISK_MAX_ADD_GB,
    apps: hostingAppMenu().map((a) => a.name),
    tlds: POPULAR_TLDS.map((t) => t.tld),
    from: {
      vps: minVps.i ?? minVps.p, vpsPlan: minVps,
      game: Math.min(...games.map((g) => g.from)),
      web: Math.min(...hosting.map((h) => h.p)),
      mail: Math.min(...email.map((m) => m.p)),
    },
    param: DEPLOY_PARAM,
  };
}

/** "No extra charge" rather than "+$0.00/mo" when an add-on is included. */
export const addonPrice = (dollars: number) => (dollars > 0 ? `+${d(dollars)}/mo` : "No extra charge");

export const money = d;

// ── /pricing markup renderers (design markup, real rows) ───────────────────
export const genreKey = (g: string) => g.toLowerCase();

export function gameTilesHtml(games: GameFam[]) {
  return games.map((g) => {
    const img = g.art ? `<img src="${esc(g.art)}" alt="" width="480" height="270" loading="lazy">` : "";
    return `<button type="button" class="gt" data-k="${esc(g.k)}" data-cat="${esc(g.genres.map(genreKey).join(" "))}" data-genre="${esc(g.genres[0] ?? "Game server")}" data-n="${esc(g.name.toLowerCase())}" data-pl="${g.pl || ""}">${img}<span>${esc(g.name)}</span></button>`;
  }).join("");
}

export function genreChipsHtml(games: GameFam[]) {
  const present = GENRE_ORDER.filter((g) => games.some((x) => x.genres.includes(g)));
  return `<button type="button" aria-pressed="true" data-c="all">All</button>`
    + present.map((g) => `<button type="button" aria-pressed="false" data-c="${genreKey(g)}">${esc(g)}</button>`).join("");
}

export function regionButtonsHtml(regions: Catalog["regions"]) {
  return regions.map((r, i) => `<button type="button"${i === 0 ? ` class="on"` : ""} data-r="${esc(r.code)}"><span class="flag flag-sm flag-${esc(r.flag)}"></span>${esc(r.city)}</button>`).join("");
}

export const introNote = (p: VpsPlan) => (p.i != null ? `${d(p.i)} ${introSpan(p.it)}, then ${d(p.p)} a month` : `${d(p.p)} a month`);
export { maxAddableExtraDiskGB, planIntroMonthlyCents };

