import "server-only";
import { deployHref } from "@/lib/deploy-intent";
import { maxAddableExtraDiskGB } from "@/lib/extra-disk";
import { esc, introSpan, productLd } from "./lib";
import {
  addonPrice, gameTilesHtml, genreChipsHtml, money, pricingCatalog, regionButtonsHtml,
} from "./pricing-catalog";

/** The design's one-line pitch per VPS plan — copy, keyed by the real plan slug. */
const VPS_LINE: Record<string, string> = {
  starter: "For side projects, bots and small APIs.",
  standard: "Most popular. Full root, NVMe and a dedicated IPv4.",
  pro: "Production apps, databases and busy sites.",
  max: "Best value. Heavy workloads with room to spare.",
