"use client";

import { useEffect } from "react";
import { SCRIPTS } from "../_pages/scripts";

/**
 * Runs a ported page's own script (nav, reveal-on-scroll, the page's widgets)
 * exactly as the design's standalone file does, after the layout has mounted
 * the Aurora runtime — the same order as the design, where aurora.built.js
 * runs before the page's JS. Also:
 *  - tags <html> with `nxm-p-<slug>-root`, the scope for the design's html/body
 *    rules (never :root:has(), which restyles the whole page on every change);
 *  - keeps the fixed nav below staging's in-flow SANDBOX banner while it is on
 *    screen, writing the nav's own `top` only when it changes.
 */
export function PageRuntime({ slug }: { slug: string }) {
  useEffect(() => {
    const page = document.querySelector<HTMLElement>(`.nxm-p-${slug}`);
    if (!page) return;
    const root = document.documentElement;
    const rootCls = `nxm-p-${slug}-root`;
    root.classList.add(rootCls);

    // setTimeout: parent (layout) effects — the Aurora mount — run after child
    // effects; the page script must see Aurora already mounted. The guard sits
    // at injection so the script runs exactly once per page load, whatever
    // React does with effects.
    setTimeout(() => {
      SCRIPTS[slug]?.().then(({ PAGE_SCRIPT }) => {
        if (page.dataset.pageMounted || !page.isConnected) return;
        page.dataset.pageMounted = "1";
        const s = document.createElement("script");
        s.textContent = PAGE_SCRIPT;
        document.body.appendChild(s);
      });
    }, 0);

    const nav = page.querySelector<HTMLElement>(".nv");
    let raf = 0, last = -1;
    const sync = () => {
      raf = 0;
      const top = Math.round(Math.max(0, page.getBoundingClientRect().top));
      if (nav && top !== last) { nav.style.top = `${top}px`; last = top; }
    };
    const queue = () => { if (!raf) raf = requestAnimationFrame(sync); };
    sync();
    addEventListener("scroll", queue, { passive: true });
    addEventListener("resize", queue);
    return () => {
      root.classList.remove(rootCls);
      removeEventListener("scroll", queue);
      removeEventListener("resize", queue);
      if (raf) cancelAnimationFrame(raf);
    };
  }, [slug]);
  return null;
}

