  const wz = $('#wizard'), panes = $$('.wpane', wz), nodes = $$('.wnode', wz), fill = $('.wtrack-fill', wz);
  const back = $('#wback'), next = $('#wnext'), sum = $('#wsum'), host = $('#hostname');
  let step = 0, timers = [], auto = 0, interacted = false;
  const val = n => { const i = wz.querySelector(`input[name="${n}"]:checked`); return i ? i.value : ''; };
  const name = () => host.value.replace(/^-+|-+$/g, '') || 'my-server';
  host.addEventListener('input', () => { const c = host.value.toLowerCase().replace(/[^a-z0-9-]/g, '-').replace(/-{2,}/g, '-'); if (c !== host.value) host.value = c; });
  wz.addEventListener('change', () => render());
  function render() {
    wz.dataset.step = String(step);
    panes.forEach(p => p.classList.toggle('on', +p.dataset.pane === step));
    nodes.forEach((n, i) => {
      n.classList.toggle('done', i < step || step === 4);
      n.classList.toggle('cur', i === step && step < 4);
      if (i === step) n.setAttribute('aria-current', 'step'); else n.removeAttribute('aria-current');
    });
    fill.style.width = (step / 4 * 80) + '%';
    back.disabled = step === 0 || step >= 3;
    back.hidden = step === 4;
    next.setAttribute('aria-disabled', String(step === 3));
    next.style.opacity = step === 3 ? '.55' : '';
    (next.querySelector('.nxm-bt') || next).textContent = step === 2 ? 'Deploy server' : step === 3 ? 'Deploying' : step === 4 ? 'Deploy another' : 'Continue';
    const parts = [val('region')]; if (step >= 1) parts.push(val('plan') + ' plan'); if (step >= 2) parts.push(val('os'));
    sum.textContent = step === 4 ? '' : parts.join(', ');
  }
  function go() {
    if (step < 2) { step++; render(); }
    else if (step === 2) { step = 3; render(); deploy(); }
    else if (step === 4) { timers.forEach(clearTimeout); timers = []; step = 0; render(); }
  }
  function deploy() {
    const region = val('region'), os = val('os'), plan = val('plan'), nm = name();
    $('#dep-name').textContent = nm;
    const tasks = [`Reserving ${plan} capacity in ${region}`, 'Provisioning NVMe volume', 'Applying network rules and DDoS protection', `Installing ${os}`, $('#backups').checked ? 'Scheduling automated backups' : 'Skipping automated backups', `Starting ${nm}`]
    const log = $('#wlog'); log.textContent = '';
    tasks.forEach(tx => { const li = document.createElement('li'); li.innerHTML = '<i aria-hidden="true"></i>'; const s = document.createElement('span'); s.textContent = tx; li.appendChild(s); log.appendChild(li); });
    const items = $$('li', log), prog = $('#wprog'); prog.style.width = '0%';
    const dur = RM ? 200 : 640;
    items.forEach((li, i) => timers.push(setTimeout(() => { if (i) items[i - 1].className = 'ok'; li.className = 'run'; prog.style.width = ((i + 0.5) / items.length * 100) + '%'; }, i * dur)));
    timers.push(setTimeout(() => { items[items.length - 1].className = 'ok'; prog.style.width = '100%'; }, items.length * dur));
    timers.push(setTimeout(() => {
      $('#online-sub').textContent = `${nm} is running in ${region}.`;
      $('#online-plan').textContent = `${plan}, ${os}`;
      step = 4; render();
    }, items.length * dur + 450));
  }
  next.addEventListener('click', () => { if (step === 3) return; stopAuto(); go(); });
  back.addEventListener('click', () => { stopAuto(); if (step > 0 && step < 3) { step--; render(); } });
  function stopAuto() { interacted = true; clearTimeout(auto); }
  wz.addEventListener('pointerdown', stopAuto, true);
  wz.addEventListener('keydown', stopAuto, true);
  render();
  if (!RM) {
    const io = watch(wz, v => {
      if (!v || interacted) return; io.disconnect();
      const seq = () => { if (interacted || step >= 3) return; go(); if (step < 3) auto = setTimeout(seq, 1500); };
      auto = setTimeout(seq, 1400);
    }, { threshold: 0.6 });
  }

