import "server-only";
import { deployHref } from "@/lib/deploy-intent";
import { CUSTOMER_REGION_LABELS } from "@/lib/node-regions";
import { COMPONENT_LABELS, OVERALL_TITLE } from "@/lib/status-copy";
import { esc, productLd } from "./lib";
import { money, pricingCatalog } from "./pricing-catalog";

/**
 * The homepage's real data (tools/nxm/wire/home.py marks where it goes):
 * starting prices, the game count and showcase, VPS plans/OS images/regions
 * in the demo wizard, datacenters on the globe, continents, and the live
 * platform status components. Everything from the same catalogue the
 * /pricing panel and checkout read.
 */

/** The design's game showcase ids -> the platform's game families. */
const STAGE_FAMILY: Record<string, string> = {
  minecraft: "minecraft", valheim: "valheim", cs2: "cs2", zomboid: "projectzomboid", rust: "rust",
  palworld: "palworld", ark: "ark", terraria: "terraria", "7dtd": "sdtd",
};

const plural = (n: number, one: string, many: string) => `${n} ${n === 1 ? one : many}`;

export async function load() {
  const c = await pricingCatalog();
  const n = c.games.length;
  const names = c.games.map((g) => g.name);
  const byFam = new Map(c.games.map((g) => [g.k, g]));

  // ── regions / globe
  const dcs = c.regions.map((r) => ({
    id: r.code, city: r.city, cc: r.flag, country: CUSTOMER_REGION_LABELS[r.code] ?? r.city,
    full: CUSTOMER_REGION_LABELS[r.code] ?? r.city, cont: r.area, lat: r.lat, lon: r.lon,
    // what the deploy wizard sells per region (hosting/email are not region-bound)
    services: ["VPS", "Game servers"], live: true,
  }));
  const links: [string, string][] = [];
  if (dcs.length <= 5) {
    for (let i = 0; i < dcs.length; i++) for (let j = i + 1; j < dcs.length; j++) links.push([dcs[i].id, dcs[j].id]);
  } else {
    const byLon = [...dcs].sort((a, b) => a.lon - b.lon);
    for (let i = 1; i < byLon.length; i++) links.push([byLon[i - 1].id, byLon[i].id]);
  }
  const continents = new Set(c.regions.map((r) => r.area)).size;
  const regionOf = (r: (typeof c.regions)[number]) => ({ label: r.label, flag: r.flag });
  const sg = c.regions.find((r) => r.code === "sgp1") ?? c.regions[0];

  // ── hero game card: Minecraft's real top slot count
  const mc = byFam.get("minecraft");
  if (!mc || !mc.pl) throw new Error("nxm home: the hero card needs a live Minecraft plan with slots");
  const hero = { on: Math.round(mc.pl * 0.64), lo: Math.round(mc.pl * 0.54), hi: Math.round(mc.pl * 0.82) };

  // ── game showcase: design entries for live families only
  const gs: Record<string, { name: string; pl: number; from: string; href: string }> = {};
  for (const [id, fam] of Object.entries(STAGE_FAMILY)) {
    const g = byFam.get(fam);
    if (g) gs[id] = { name: g.name, pl: g.pl, from: money(g.from), href: deployHref({ service: "game", gameFamily: g.k }) };
  }
  const gs0 = Object.values(gs)[0];
  if (!gs0) throw new Error("nxm home: no showcase game is live");

  // ── demo wizard: real regions, VPS plans and the newest image per OS family
  const vpsDef = c.vps.find((p) => p.slug === "standard") ?? c.vps[Math.floor((c.vps.length - 1) / 2)];
  const osByFam = new Map<string, (typeof c.os)[number]>();
  for (const o of c.os) {
    const cur = osByFam.get(o.fam);
    if (!cur || o.v.localeCompare(cur.v, undefined, { numeric: true }) > 0) osByFam.set(o.fam, o);
  }
  const oses = [...osByFam.values()].sort((a, b) => (a.v === c.os0 ? -1 : b.v === c.os0 ? 1 : 0));
  const radio = (name: string, value: string, checked: boolean, inner: string) =>
    `<label class="opt"><input type="radio" name="${name}" value="${esc(value)}"${checked ? " checked" : ""}>${inner}</label>`;

  const cheapest = c.from.vpsPlan;
  const promo = c.hostingPromo;

  return {
    data: {
      dcs, links, gameCount: n, gs, hero,
      region0: regionOf(c.regions[0]),
      regionByCity: Object.fromEntries(c.regions.map((r) => [r.city, regionOf(r)])),
      status: Object.entries(COMPONENT_LABELS),
      statusTitle: OVERALL_TITLE,
    },
    slots: {
      "net.continentsShort": `${c.regions.length === 1 ? "Datacenter" : "Datacenters"} on ${plural(continents, "continent", "continents")}`,
      "net.sentence": `${plural(c.regions.length, "datacenter", "datacenters")} across ${plural(continents, "continent", "continents")}`,
      "hero.on": String(hero.on), "hero.max": String(mc.pl), "hero.region": sg.city, "hero.flag": sg.flag,
      "from.vps": money(c.from.vps), "from.vpsAnnual": money(cheapest.p * (1 - (c.terms[12] ?? 0))),
      "from.game": money(c.from.game), "from.web": money(c.from.web), "from.mail": money(c.from.mail),
      "games.count": String(n),
      "games.three": n > 3 ? `${names.slice(0, 3).join(", ")} and ${n - 3} more` : names.join(", "),
      "games.four": n > 5 ? `${names.slice(1, 5).join(", ")} and ${n - 5} more` : names.slice(1).join(", "),
      "games.other": n > 1 ? `For ${names[0]} and ${n - 1} other games.` : `For ${names[0]}.`,
      "gs.from0": gs0.from,
      "web.badge:html": promo ? `<span class="pv-badge">${esc(promo)}</span>` : "",
      "web.note:html": promo ? `<span class="rc-note ok">${esc(promo)}</span>` : `<span class="rc-note">Billed monthly</span>`,
      "web.fine": promo ? "Shared Hosting's first month is free, then it's billed at the monthly price shown. " : "",
      "wz.regions:html": c.regions.map((r, i) => radio("region", r.city, i === 0,
        `<b><span class="flag flag-${esc(r.flag)}" aria-hidden="true"></span>${esc(r.city)}</b><small>${esc(CUSTOMER_REGION_LABELS[r.code] ?? r.city)}</small>`)).join("\n            "),
      "wz.plans:html": c.vps.map((p) => radio("plan", p.n, p === vpsDef,
        `<b>${esc(p.n)}</b><span class="spec"><span>${p.cpu} vCPU</span><span>${p.ram} GB memory</span><span>${p.disk} GB NVMe</span></span>`)).join("\n            "),
      "wz.os:html": oses.map((o) => radio("os", o.v, o.v === c.os0, `<b>${esc(o.t)}</b><small>${esc(o.sub)}</small>`)).join("\n            "),
      "wz.region0": c.regions[0].city, "wz.plan0": vpsDef.n, "wz.os0": c.os0,
      "dev.plan": `${vpsDef.n}, ${vpsDef.cpu} vCPU, ${vpsDef.ram} GB`,
    } as Record<string, string>,
    jsonLd: [
      productLd("Nxeon Cloud VPS", "NVMe cloud VPS with full root access, one-click apps, game servers, and an optional dedicated IPv4.",
        "/", c.vps.map((p) => ({ name: `${p.n} VPS`, price: p.i ?? p.p }))),
    ],
  };
}

