    }
    if (w === 1440) console.log(await p.evaluate(() => ({ status: document.querySelector('#status-title').textContent, list: document.querySelector('#status-list').textContent, hud: document.querySelector('#hud-reg').textContent, cta: document.querySelector('#gs-cta').getAttribute('href'), tabs: document.querySelectorAll('.gs-tab').length, more: document.querySelector('.gs-more')?.textContent })));
    console.log(w, errs); await p.close();
  }
  await b.close();
})();
EOF
