cd /tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad && cat > mo.js <<'EOF'
const { chromium } = require('/opt/nxeon/node_modules/playwright');
(async () => {
  const b = await chromium.launch(); const p = await b.newPage();
  await p.addInitScript(() => {
    window.__log = [];
    const t0 = performance.now();
    new MutationObserver(ms => { for (const m of ms) {
      if (m.target.id === 'main' || (m.target.classList && m.target.classList.contains('nxm-home'))) window.__log.push(Math.round(performance.now()-t0) + ' childList on ' + (m.target.id || m.target.className) + ' +' + m.addedNodes.length + ' -' + m.removedNodes.length);
      if (m.target.id === 'gs-strip') window.__log.push(Math.round(performance.now()-t0) + ' gs-strip ' + m.addedNodes.length);
      for (const n of m.addedNodes) if (n.tagName === 'SCRIPT' && n.textContent.startsWith('var __NXM')) window.__log.push(Math.round(performance.now()-t0) + ' home script added');
    } }).observe(document, { childList: true, subtree: true });
  });
  await p.goto('http://localhost:3033/nxm', { waitUntil: 'networkidle', timeout: 90000 }); await p.waitForTimeout(4000);
  console.log((await p.evaluate(() => window.__log)).join('\n'));
  await b.close();
})();
EOF
node mo.js

